mapper.select:
SELECT address_id, member_id, recipient, phone, phone_norm, zipcode, road_address, detail_address,
       entrance_method, delivery_memo, is_default, last_used_at, created_at, updated_at
  FROM MEMBER_ADDRESSES
 WHERE member_id = #{memberId}
   AND address_id = #{addressId}
   AND del_yn = 'N'

mapper.update:
UPDATE MEMBER_ADDRESSES
   SET recipient = #{recipient}, phone = #{phone}, phone_norm = #{phoneNorm}, zipcode = #{zipcode},
       road_address = #{roadAddress}, detail_address = #{detailAddress},
       entrance_method = #{entranceMethod}, delivery_memo = #{deliveryMemo}, updated_at = #{updatedAt}
 WHERE member_id = #{memberId}
   AND address_id = #{addressId}
   AND del_yn = 'N'

UPDATE MEMBER_ADDRESSES
   SET del_yn = 'Y', updated_at = #{updatedAt}
 WHERE member_id = #{memberId}
   AND address_id = #{addressId}
   AND del_yn = 'N'

UPDATE MEMBER_ADDRESSES
   SET is_default = 'Y'
 WHERE member_id = #{memberId}
   AND address_id = #{addressId}
   AND del_yn = 'N'
